// Shape n8n's error payload into the workflow_runs record the backend expects.
// Secrets are stripped: an error body can otherwise carry an Authorization header.
const SENSITIVE = /authorization|token|secret|api[_-]?key|password/i;

function scrub(value, depth = 0) {
  if (depth > 4 || value == null) return value;
  if (Array.isArray(value)) return value.map((v) => scrub(v, depth + 1));
  if (typeof value !== 'object') return value;
  const out = {};
  for (const [k, v] of Object.entries(value)) {
    out[k] = SENSITIVE.test(k) ? '[redacted]' : scrub(v, depth + 1);
  }
  return out;
}

const results = [];
for (const item of $input.all()) {
  const e = item.json.execution ?? {};
  const w = item.json.workflow ?? {};
  const code = (w.name ?? '').split(' ')[0] || 'UNKNOWN';
  results.push({
    json: {
      workflow_code: code,
      n8n_execution_id: String(e.id ?? ''),
      status: 'dead_letter',
      error: String(e.error?.message ?? 'Unknown workflow failure').slice(0, 2000),
      failed_node: e.lastNodeExecuted ?? null,
      input_payload: scrub(e.error?.node ?? {}),
      finished_at: new Date().toISOString(),
    },
  });
}
return results;
